"""Original NFL team badges for the league site: one emblem per team drawn from city or fan identity (never the club's
mascot or mark), the abbreviation in one of six open-licence typefaces, and the team's two colours.
Run: python3 src/nfl-badges/build_review.py  -> writes src/nfl-badges/badges.json and /tmp/badges_review.html
Nothing here is used by the site until the set is approved."""
import json, re, math, sys
C='currentColor'; P='var(--p)'
def rays(n, x, y, w, h, rx=2):  # n rectangles around the centre (50,50)
    return ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" transform="rotate({i*360/n:.1f} 50 50)"/>' for i in range(n))
